using System;
using System.Collections.Generic;
using System.Text;

namespace Sekai.MusicScoreMaker.Ingame.Utilities
{
	internal static class HersheyStrokeFont
	{
		private const string EncodedData = "";
		private static readonly Dictionary<char, int> CharacterNumbers = new Dictionary<char, int>
		{
			['A']=501,['B']=502,['C']=503,['D']=504,['E']=505,['F']=506,['G']=507,['H']=508,['I']=509,['J']=510,['K']=511,['L']=512,['M']=513,['N']=514,['O']=515,['P']=516,['Q']=517,['R']=518,['S']=519,['T']=520,['U']=521,['V']=522,['W']=523,['X']=524,['Y']=525,['Z']=526,
			['a']=601,['b']=602,['c']=603,['d']=604,['e']=605,['f']=606,['g']=607,['h']=608,['i']=609,['j']=610,['k']=611,['l']=612,['m']=613,['n']=614,['o']=615,['p']=616,['q']=617,['r']=618,['s']=619,['t']=620,['u']=621,['v']=622,['w']=623,['x']=624,['y']=625,['z']=626,
			[' ']=699,['0']=700,['1']=701,['2']=702,['3']=703,['4']=704,['5']=705,['6']=706,['7']=707,['8']=708,['9']=709,['.']=710,[',']=711,[':']=712,[';']=713,['!']=714,['?']=715,['\"']=717,['$']=719,['/']=720,['(']=721,[')']=722,['|']=723,['-']=724,['+']=725,['=']=726,['\'']=731,['#']=733,['&']=734,['\\']=804,['_']=999,['*']=2219,['[']=2223,[']']=2224,['{']=2225,['}']=2226,['<']=2241,['>']=2242,['~']=2246,['%']=2271,['@']=2273
		};
		private static Dictionary<int, Glyph> _glyphs;

		internal sealed class Glyph
		{
			public float Width;
			public readonly List<List<ArtStrokePoint>> Paths = new List<List<ArtStrokePoint>>();
		}

		public static Glyph Get(char character)
		{
			if (character == '^') return MakeGlyph(16, new ArtStrokePoint(2, 14), new ArtStrokePoint(8, 5), new ArtStrokePoint(14, 14));
			if (character == '`') return MakeGlyph(10, new ArtStrokePoint(3, 5), new ArtStrokePoint(7, 9));
			if (!CharacterNumbers.TryGetValue(character, out int number)) throw new NotSupportedException($"Hershey does not contain '{character}'.");
			EnsureLoaded();
			if (!_glyphs.TryGetValue(number, out Glyph glyph)) throw new InvalidOperationException($"Missing Hershey glyph {number}.");
			return glyph;
		}

		private static Glyph MakeGlyph(float width, params ArtStrokePoint[] points)
		{
			Glyph glyph = new Glyph { Width = width };
			glyph.Paths.Add(new List<ArtStrokePoint>(points));
			return glyph;
		}

		private static void EnsureLoaded()
		{
			if (_glyphs != null) return;
			_glyphs = new Dictionary<int, Glyph>();
			string data = Encoding.ASCII.GetString(Convert.FromBase64String(EncodedData));
			foreach (string rawLine in data.Split(new[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries))
			{
				if (rawLine.Length < 10 || !int.TryParse(rawLine.Substring(0, 5), out int number)) continue;
				int left = rawLine[8] - 'R';
				int right = rawLine[9] - 'R';
				Glyph glyph = new Glyph { Width = right - left };
				List<ArtStrokePoint> path = new List<ArtStrokePoint>();
				for (int i = 10; i + 1 < rawLine.Length; i += 2)
				{
					int x = rawLine[i] - 'R';
					int y = rawLine[i + 1] - 'R';
					if (x == -50 && y == 0)
					{
						if (path.Count >= 2) glyph.Paths.Add(path);
						path = new List<ArtStrokePoint>();
					}
					else path.Add(new ArtStrokePoint(x - left, -y + 11));
				}
				if (path.Count >= 2) glyph.Paths.Add(path);
				_glyphs[number] = glyph;
			}
		}
	}
}
